import io.github.vmzakharov.ecdataframe.dsl.*;
import io.github.vmzakharov.ecdataframe.util.PrinterFactory;
import org.junit.Test;
import static org.junit.Assert.assertEquals;

public class PrettyPrintVisitorTest {

    @Test
    public void exprToStringTest() {
        Expression expression = new DecimalExpr(10);
        String result = PrettyPrintVisitor.exprToString(expression);
        assertEquals("10", result);
    }

    @Test
    public void visitAssignExprTest() {
        PrettyPrintVisitor visitor = new PrettyPrintVisitor(PrinterFactory.getDefaultPrinter());
        AssingExpr assingExpr = new AssingExpr(new VarExpr("num"), new DecimalExpr(10));
        assingExpr.accept(visitor);
    }

    @Test
    public void visitBinaryExprTest() {
        PrettyPrintVisitor visitor = new PrettyPrintVisitor(PrinterFactory.getDefaultPrinter());
        BinaryExpr binaryExpr = new BinaryExpr(new DecimalExpr(10), Operator.ADD, new DecimalExpr(5));
        binaryExpr.accept(visitor);
    }

    @Test
    public void visitUnaryExprTest() {
        PrettyPrintVisitor visitor = new PrettyPrintVisitor(PrinterFactory.getDefaultPrinter());
        UnaryExpr unaryExpr = new UnaryExpr(new DecimalExpr(5), Operator.MINUS);
        unaryExpr.accept(visitor);
    }

    @Test
    public void visitConstExprTest() {
        PrettyPrintVisitor visitor = new PrettyPrintVisitor(PrinterFactory.getDefaultPrinter());
        Value value = ValueType.DECIMAL.newValue(10);
        visitor.visitConstExpr(value);
    }

    @Test
    public void visitFunctionCallExprTest() {
        PrettyPrintVisitor visitor = new PrettyPrintVisitor(PrinterFactory.getDefaultPrinter());
        FunctionCallExpr functionCallExpr = new FunctionCallExpr("add", new DecimalExpr(5));
        functionCallExpr.accept(visitor);
    }

    @Test
    public void visitPropertyPathExprTest() {
        PrettyPrintVisitor visitor = new PrettyPrintVisitor(PrinterFactory.getDefaultPrinter());
        PropertyPathExpr propertyPathExpr = new PropertyPathExpr("age");
        propertyPathExpr.accept(visitor);
    }

    @Test
    public void visitAnonymousScriptExprTest() {
        PrettyPrintVisitor visitor = new PrettyPrintVisitor(PrinterFactory.getDefaultPrinter());
        AnonymousScript anonymousScript = new AnonymousScript();
        anonymousScript.accept(visitor);
    }

    @Test
    public void visitFunctionScriptExprTest() {
        PrettyPrintVisitor visitor = new PrettyPrintVisitor(PrinterFactory.getDefaultPrinter());
        FunctionScript functionScript = new FunctionScript("<anonymous>");
        functionScript.accept(visitor);
    }

    @Test
    public void visitStatementSequenceScriptTest() {
        PrettyPrintVisitor visitor = new PrettyPrintVisitor(PrinterFactory.getDefaultPrinter());
        StatementSequenceScript statementSequenceScript = new StatementSequenceScript();
        statementSequenceScript.accept(visitor);
    }

    @Test
    public void visitVarExprTest() {
        PrettyPrintVisitor visitor = new PrettyPrintVisitor(PrinterFactory.getDefaultPrinter());
        VarExpr varExpr = new VarExpr("num");
        varExpr.accept(visitor);
    }

    @Test
    public void visitProjectionExprTest() {
        PrettyPrintVisitor visitor = new PrettyPrintVisitor(PrinterFactory.getDefaultPrinter());
        ProjectionExpr projectionExpr = new ProjectionExpr(new VarExpr("num"));
        projectionExpr.accept(visitor);
    }

    @Test
    public void visitAliasExprTest() {
        PrettyPrintVisitor visitor = new PrettyPrintVisitor(PrinterFactory.getDefaultPrinter());
        AliasExpr aliasExpr = new AliasExpr(new VarExpr("num"), "number");
        aliasExpr.accept(visitor);
    }

    @Test
    public void visitVectorExprTest() {
        PrettyPrintVisitor visitor = new PrettyPrintVisitor(PrinterFactory.getDefaultPrinter());
        VectorExpr vectorExpr = new VectorExpr();
        vectorExpr.accept(visitor);
    }

    @Test
    public void visitIndexExprTest() {
        PrettyPrintVisitor visitor = new PrettyPrintVisitor(PrinterFactory.getDefaultPrinter());
        IndexExpr indexExpr = new IndexExpr(new VarExpr("vec"), new DecimalExpr(5));
        indexExpr.accept(visitor);
    }

    @Test
    public void visitDecimalExprTest() {
        PrettyPrintVisitor visitor = new PrettyPrintVisitor(PrinterFactory.getDefaultPrinter());
        DecimalExpr decimalExpr = new DecimalExpr(10);
        decimalExpr.accept(visitor);
